function createBibFileReader({onContent,onState=()=>{}}){
  let generation=0,pending=false;
  const state=()=>({pending});
  function publish(message){onState({pending,message});}
  function cancel(){
    generation++;
    if(pending){pending=false;publish('已取消上次文件读取；当前输入保留。');}
  }
  async function read(file){
    const token=++generation;
    if(!file){pending=false;publish('当前输入保留；请选择 .bib 文件。');return false;}
    if(file.size>5_000_000){pending=false;publish('文件超过本版 5 MB 预览上限；请改用较小的 .bib 文件。');return false;}
    pending=true;publish(`正在从本机读取 ${file.name}…`);
    try{
      const content=await file.text();
      if(token!==generation)return false;
      onContent(content);
      pending=false;publish(`已读入 ${file.name}；文件没有上传。`);
      return true;
    }catch(error){
      if(token!==generation)return false;
      pending=false;publish(`无法读取文件：${error instanceof Error?error.message:String(error)}`);
      return false;
    }
  }
  return {read,cancel,state};
}
